import{_ as i,o,c as e,a3 as t}from"./chunks/framework.D8u9WiMi.js";const m=JSON.parse('{"title":"十八号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/18.md","filePath":"listOfEvents/2026/march/18.md"}'),a={name:"listOfEvents/2026/march/18.md"};function s(c,l,n,r,d,_){return o(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="十八号的流水账" tabindex="-1">十八号的流水账 <a class="header-anchor" href="#十八号的流水账" aria-label="Permalink to &quot;十八号的流水账&quot;">​</a></h1><ol><li>泛型：参数化类型 <ol><li>细节：因为java文件在编译时会转换成class文件，这时会擦除泛型，但泛型的基础类是Object类，而基本数据类型int不是Object的子类，没法自动转，而泛型需要Object来实现通用化，利用了多态的特性</li><li>泛型类 <ol><li>在类的定义中使用泛型类型参数的类</li></ol></li><li>泛型方法 <ol><li>在方法定义中使用泛型类型参数的方法</li></ol></li><li>泛型接口 <ol><li>在接口的定义中使用泛型类型参数的接口</li></ol></li><li>通配符？ <ol><li><code>&lt;? extends E&gt;</code>：表示可以传递E或者E所有的子类类型</li><li><code>&lt;? super E&gt;</code>：表示可以传递E或者E所有的父类类型</li><li>泛型不具备继承性，数据具备继承性</li></ol></li></ol></li><li>知识加油站 <ol><li>数据结构 <ol><li>栈：先进后出</li><li>队列：先进先出</li><li>数组：查找很快，但插入删除就慢了</li><li>链表：增删快，插入慢，时间辐照度O(n) <ol><li>链表节点都是独立的，在内存在都是不连续的</li></ol></li><li>数： <ol><li>二叉树 <ol><li>节点和度，度最大不超过2，查找比链表快，但如果只有一条子树，那就和链表是一样了</li></ol></li><li>二叉查找树 <ol><li>度最大不超过2</li><li>任意节点上左子树的节点都小于当前节点</li><li>任意节点上右子树的节点都大于当前节点</li></ol></li><li>平衡二叉树 <ol><li>会根据规则自平衡</li><li>高度差最大不能大于1</li><li>任意节点到的子树都有个平衡二叉树</li><li>旋转： <ol><li>左旋：右节点变成根节点，原根节点作为新根节点的左子树，原右节点的左子树，拆给原根节点(现左节点)作为右子树</li><li>右旋：左节点变成根节点，原根节点作为新的根节点的左子树，原左节点的右子树，拆给原根节点(现右节点)作为左子树</li></ol></li></ol></li><li>红黑树 <ol><li>每个节点都有颜色标记，只能是红色或黑色</li><li>红色不能相连，如当前节点时红色，那么父节点和子节点就不能是红色</li><li>每个节点都还有自己的两个<code>Nil</code>空叶节点，叶节点是黑色的</li><li>根节点永远是黑色的</li><li>从任意节点触发，任意叶节点，经过的黑节点都是相等的</li></ol></li></ol></li></ol></li><li>可变参数：<code>数据类型...数据名称</code>：不确定需要接收多少参数时使用</li><li>lambda表达式：算是个语法糖，在抽象类实现函数式接口时使用，函数式接口是只有一个抽象方法的接口。</li></ol></li><li>函数式接口：只包含一个抽象方法的接口</li><li>Equals()方法和==运算符的区别 <ol><li>==其实就是直接在栈中的值 <ol><li>基本数据类型，如：int boolean 或者 &quot;&quot; 在栈中存的是值</li><li>引用数据类型存储的是地址：所以两个引用数据类型内部的值一样，但地址不一样也不相等</li></ol></li><li>equals对比两个对象的值是否相等，可以做规则的重写</li></ol></li><li>java小游戏 <ol><li>创建两方人物</li><li>whil循环，每次循环判断自己死了吗，</li><li>从第二场开始，没赢一场地方属性都会提升 <ol><li>内部回合战斗开始，也是whil循环</li><li>每次都输出双方的血量信息</li><li>判断对方死了吗</li></ol></li></ol></li></ol><p>加了点ai和agent的文档</p><p>在SumUp上加了退休目标和当前进度。</p><p>回头是不是可以写上给自己的目标</p>',5)])])}const u=i(a,[["render",s]]);export{m as __pageData,u as default};
